  const [formState, setFormState] = useState<FormState>({
    name: '',
    rewardType: '',
    requiredPoints: '',
    discountValue: '',
    freeProductId: '',
    isActive: true,
    description: '',
  });
  const [showAlert, setShowAlert] = useState(false);
  const [itemToDelete, setItemToDelete] = useState<PosRewardCatalogItem | null>(null);
  const [page, setPage] = useState(0);
  const [isInfiniteDisabled, setInfiniteDisabled] = useState(false);

  const [popoverState, setPopoverState] = useState({
    showAlertPopover: false,
    showMailPopover: false,
    event: undefined as Event | undefined,
  });

  const presentAlertPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showAlertPopover: true, event: e.nativeEvent });
  const dismissAlertPopover = () =>
    setPopoverState({ ...popoverState, showAlertPopover: false });
  const presentMailPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showMailPopover: true, event: e.nativeEvent });
  const dismissMailPopover = () =>
    setPopoverState({ ...popoverState, showMailPopover: false });

  const PAGE_SIZE = 20;
  const allItemsRef = useRef<PosRewardCatalogItem[]>([]);

  const loadItems = async (initialLoad = true, newPage = 0) => {
    setLoading(true);
    try {
      const fetchedItems = await getAllPosRewardCatalogItems(companyId);
      allItemsRef.current = fetchedItems;

      if (initialLoad) {
        setItems(fetchedItems.slice(0, PAGE_SIZE));
        setInfiniteDisabled(fetchedItems.length <= PAGE_SIZE);
        setPage(1);
      } else {
        const startIndex = newPage * PAGE_SIZE;
        const endIndex = startIndex + PAGE_SIZE;
        const newItems = fetchedItems.slice(startIndex, endIndex);
        setItems((prev) => [...prev, ...newItems]);
        setInfiniteDisabled(endIndex >= fetchedItems.length);
        setPage(newPage + 1);
      }
    } catch (err) {
      setError((err as Error).message ?? 'Error loading POS Reward Catalog Items');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadItems();
  }, [companyId]);

  useIonViewWillEnter(() => {
    loadItems();
