    } else {
      setEditItem(null);
      setFormState({
        name: '',
        rewardType: '',
        requiredPoints: '',
        discountValue: '',
        freeProductId: '',
        isActive: true,
        description: '',
      });
    }
    setShowModal(true);
  };

  const handleCloseModal = () => {
    setShowModal(false);
    setEditItem(null);
    setError('');
  };

  const handleSave = async () => {
    if (!formState.name || !formState.rewardType || formState.requiredPoints === '') {
      setError('Name, Reward Type, and Required Points are mandatory.');
      return;
    }

    setSaving(true);
    setError('');
    try {
      const payload = {
        companyId,
        name: formState.name,
        rewardType: formState.rewardType,
        requiredPoints: Number(formState.requiredPoints),
        discountValue: formState.discountValue !== '' ? Number(formState.discountValue) : null,
        freeProductId: formState.freeProductId !== '' ? Number(formState.freeProductId) : null,
        isActive: formState.isActive,
        description: formState.description,
      };

      if (editItem) {
        await updatePosRewardCatalogItem(editItem.catalogItemId, payload);
      } else {
        await createPosRewardCatalogItem(payload);
      }
      await loadItems(true); // Reload all items after save
      handleCloseModal();
    } catch (err) {
      setError((err as Error).message ?? 'Error saving POS Reward Catalog Item');
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async () => {
    if (itemToDelete) {
      setSaving(true);
      setError('');
      try {
        await deletePosRewardCatalogItem(itemToDelete.catalogItemId, companyId);
        await loadItems(true); // Reload all items after delete
        setShowAlert(false);
        setItemToDelete(null);
      } catch (err) {
        setError((err as Error).message ?? 'Error deleting POS Reward Catalog Item');
      } finally {
        setSaving(false);
      }
    }
  };

